IF DB_ID(N'QL_TraSua') IS NULL CREATE DATABASE QL_TraSua;
GO
USE QL_TraSua;
GO
IF OBJECT_ID('dbo.ChiTietHoaDon','U') IS NOT NULL DROP TABLE ChiTietHoaDon; IF OBJECT_ID('dbo.HoaDon','U') IS NOT NULL DROP TABLE HoaDon; IF OBJECT_ID('dbo.MonUong','U') IS NOT NULL DROP TABLE MonUong; IF OBJECT_ID('dbo.DanhMucMon','U') IS NOT NULL DROP TABLE DanhMucMon;
CREATE TABLE DanhMucMon(MaDM INT IDENTITY PRIMARY KEY,TenDM NVARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE MonUong(MaMon INT IDENTITY PRIMARY KEY,TenMon NVARCHAR(100) NOT NULL,GiaBan DECIMAL(18,0) NOT NULL CHECK(GiaBan>=0),DangBan BIT NOT NULL DEFAULT 1,MaDM INT NOT NULL REFERENCES DanhMucMon(MaDM));
CREATE TABLE HoaDon(MaHD INT IDENTITY PRIMARY KEY,NgayLap DATETIME NOT NULL DEFAULT GETDATE(),TongTien DECIMAL(18,0) NOT NULL,HinhThucTT NVARCHAR(20) NOT NULL,DaThanhToan BIT NOT NULL DEFAULT 0);
CREATE TABLE ChiTietHoaDon(MaHD INT NOT NULL REFERENCES HoaDon(MaHD),MaMon INT NOT NULL REFERENCES MonUong(MaMon),SoLy INT NOT NULL CHECK(SoLy>0),DonGia DECIMAL(18,0) NOT NULL,CONSTRAINT PK_ChiTietHoaDon PRIMARY KEY(MaHD,MaMon));
